:root {
  --green: #00ff88;
  --red: #ff2244;
  --yellow: #ffcc00;
  --bg: #020508;
  --panel: #060c12;
  --border: #0d2030;
  --text: #7aaabb;
}

* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
}

body {
  background: var(--bg);
  color: var(--text);
  font-family: 'Share Tech Mono', monospace;
  overflow-x: hidden;
  cursor: crosshair;
}

/* SCANLINES */
body::before {
  content: '';
  position: fixed;
  inset: 0;
  background: repeating-linear-gradient(0deg, transparent, transparent 2px, rgba(0, 255, 136, 0.012) 2px, rgba(0, 255, 136, 0.012) 4px);
  pointer-events: none;
  z-index: 999;
}

/* GRID BG */
.grid-bg {
  position: fixed;
  inset: 0;
  background-image:
    linear-gradient(rgba(0, 255, 136, 0.025) 1px, transparent 1px),
    linear-gradient(90deg, rgba(0, 255, 136, 0.025) 1px, transparent 1px);
  background-size: 50px 50px;
  pointer-events: none;
  z-index: 0;
}

/* ---- HERO ---- */
.hero {
  position: relative;
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  text-align: center;
  overflow: hidden;
}

.hero-banner {
  position: absolute;
  inset: 0;
  background-image: url('data:image/jpeg;base64,');
  background-size: cover;
  background-position: center;
  filter: brightness(0.35) saturate(1.2);
  z-index: 1;
}

.hero-banner::after {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(to bottom, transparent 40%, var(--bg) 100%);
}

.hero-content {
  position: relative;
  z-index: 2;
  padding: 40px 20px;
}

.hero-avatar {
  width: 140px;
  height: 140px;
  border-radius: 50%;
  border: 2px solid var(--green);
  box-shadow: 0 0 30px #00ff8855, 0 0 80px #00ff8822;
  object-fit: cover;
  margin-bottom: 32px;
  animation: pulse-avatar 3s ease-in-out infinite;
}

@keyframes pulse-avatar {

  0%,
  100% {
    box-shadow: 0 0 30px #00ff8855, 0 0 80px #00ff8822;
  }

  50% {
    box-shadow: 0 0 50px #00ff88aa, 0 0 120px #00ff8844;
  }
}

.hero-ticker {
  font-family: 'Bebas Neue', sans-serif;
  font-size: clamp(80px, 18vw, 180px);
  letter-spacing: 0.08em;
  line-height: 1;
  color: var(--green);
  text-shadow: 0 0 40px #00ff8866, 0 0 100px #00ff8822;
  animation: flicker 8s infinite;
}

@keyframes flicker {

  0%,
  95%,
  100% {
    opacity: 1;
  }

  96% {
    opacity: 0.7;
  }

  97% {
    opacity: 1;
  }

  98% {
    opacity: 0.85;
  }
}

.hero-tagline {
  font-family: 'Rajdhani', sans-serif;
  font-size: clamp(14px, 3vw, 22px);
  font-weight: 300;
  letter-spacing: 0.35em;
  color: #4a7080;
  text-transform: uppercase;
  margin-top: 12px;
  margin-bottom: 48px;
}

.hero-quote {
  font-size: 13px;
  line-height: 1.9;
  color: #3a6070;
  max-width: 560px;
  margin: 0 auto 48px;
  border-left: 2px solid var(--green);
  padding-left: 20px;
  text-align: left;
}

.hero-quote span {
  color: var(--green);
}

.btn-primary {
  display: inline-block;
  font-family: 'Bebas Neue', sans-serif;
  font-size: 20px;
  letter-spacing: 0.2em;
  padding: 14px 48px;
  border: 1px solid var(--green);
  color: var(--green);
  text-decoration: none;
  position: relative;
  overflow: hidden;
  transition: all 0.3s;
}

.btn-primary::before {
  content: '';
  position: absolute;
  inset: 0;
  background: var(--green);
  transform: scaleX(0);
  transform-origin: left;
  transition: transform 0.3s;
  z-index: -1;
}

.btn-primary:hover {
  color: #000;
}

.btn-primary:hover::before {
  transform: scaleX(1);
}

.scroll-hint {
  position: absolute;
  bottom: 30px;
  left: 50%;
  transform: translateX(-50%);
  font-size: 10px;
  letter-spacing: 0.3em;
  color: #1a3040;
  animation: bounce 2s infinite;
  z-index: 2;
}

@keyframes bounce {

  0%,
  100% {
    transform: translateX(-50%) translateY(0)
  }

  50% {
    transform: translateX(-50%) translateY(6px)
  }
}

/* ---- HUMAN INDEX ---- */
.section {
  position: relative;
  z-index: 1;
  padding: 80px 20px;
}

.container {
  max-width: 900px;
  margin: 0 auto;
}

.section-label {
  font-size: 10px;
  letter-spacing: 0.5em;
  color: #1a4050;
  text-transform: uppercase;
  margin-bottom: 8px;
}

.section-title {
  font-family: 'Bebas Neue', sans-serif;
  font-size: clamp(36px, 6vw, 64px);
  letter-spacing: 0.05em;
  color: #e0f0f8;
  margin-bottom: 48px;
}

/* BIG INDEX DISPLAY */
.index-main {
  background: var(--panel);
  border: 1px solid var(--border);
  border-top: 2px solid var(--green);
  padding: 48px 40px;
  position: relative;
  margin-bottom: 24px;
  transition: border-color 1s;
}

.index-main.warn {
  border-top-color: var(--yellow);
}

.index-main.danger {
  border-top-color: var(--red);
}

.index-corner {
  position: absolute;
  top: 16px;
  right: 20px;
  font-size: 10px;
  letter-spacing: 0.3em;
  color: #1a3040;
}

.index-label {
  font-size: 11px;
  letter-spacing: 0.4em;
  color: #2a5060;
  margin-bottom: 16px;
}

.index-number {
  font-family: 'Bebas Neue', sans-serif;
  font-size: clamp(80px, 16vw, 140px);
  line-height: 1;
  color: var(--green);
  text-shadow: 0 0 40px #00ff8855;
  transition: color 1s, text-shadow 1s;
  letter-spacing: -0.02em;
}

.index-number.warn {
  color: var(--yellow);
  text-shadow: 0 0 40px #ffcc0055;
}

.index-number.danger {
  color: var(--red);
  text-shadow: 0 0 40px #ff224455;
}

.index-status {
  font-size: 12px;
  letter-spacing: 0.3em;
  color: var(--green);
  margin-top: 8px;
  transition: color 1s;
}

.index-status.warn {
  color: var(--yellow);
}

.index-status.danger {
  color: var(--red);
  animation: blink 1s infinite;
}

@keyframes blink {
  50% {
    opacity: 0.3
  }
}

/* ══════════════════════════════════════════════
   GLITCH / ALARM MODE  —  CINEMATIC EDITION
══════════════════════════════════════════════ */

/* RGB-split glitch on elements */
@keyframes glitch {
  0%,100% { transform: translate(0) skewX(0);       text-shadow:  2px 0 #ff0000, -2px 0 #00ff88; }
  10%      { transform: translate(-4px) skewX(-1.5deg); text-shadow: -6px 0 #ff0000,  6px 0 #00ffff; }
  20%      { transform: translate( 5px) skewX( 2deg);   text-shadow:  5px 0 #ff2244, -5px 0 #00ff88; }
  30%      { transform: translate(-2px) skewX(-0.8deg); text-shadow: -3px 0 #ff0000,  3px 0 #00ffff; }
  40%      { transform: translate( 6px) skewX( 2.5deg); text-shadow:  7px 0 #ff2244, -7px 0 #00ff88; }
  50%      { transform: translate(-5px) skewX(-2deg);   text-shadow: -5px 0 #ff0000,  5px 0 #00ffff; }
  60%      { transform: translate( 3px) skewX( 1deg);   text-shadow:  4px 0 #ff2244, -4px 0 #00ff88; }
  70%      { transform: translate(-6px) skewX(-2.5deg); text-shadow: -7px 0 #ff0000,  7px 0 #00ffff; }
  80%      { transform: translate( 2px) skewX( 0.8deg); text-shadow:  2px 0 #ff2244, -2px 0 #00ff88; }
  90%      { transform: translate(-3px) skewX(-1deg);   text-shadow: -4px 0 #ff0000,  4px 0 #00ffff; }
}

/* Jerky screen shake — steps(1) = digital snap */
@keyframes screenShake {
  0%   { transform: translate(  0,   0); }
  11%  { transform: translate(-5px,  2px); }
  22%  { transform: translate( 4px, -3px); }
  33%  { transform: translate(-3px,  5px); }
  44%  { transform: translate( 6px, -1px); }
  55%  { transform: translate(-4px,  3px); }
  66%  { transform: translate( 5px, -5px); }
  77%  { transform: translate(-6px,  1px); }
  88%  { transform: translate( 3px, -2px); }
  100% { transform: translate(-2px,  4px); }
}

/* Page-level chromatic aberration */
@keyframes rgbBodyShift {
  0%,100% { filter: none; }
  20%  { filter: contrast(1.12) saturate(1.4) hue-rotate( 6deg); }
  40%  { filter: contrast(1.18) saturate(1.6) hue-rotate(-10deg) brightness(1.08); }
  60%  { filter: contrast(1.10) saturate(1.3) hue-rotate( 4deg); }
  80%  { filter: contrast(1.15) saturate(1.5) hue-rotate( -6deg) brightness(1.05); }
}

/* Pulsing red glow on index panel */
@keyframes alarmPulse {
  0%   { box-shadow: inset 0 0 20px #ff224411; border-top-color: #ff2244; }
  35%  { box-shadow: 0 0 60px 12px #ff224455, inset 0 0 100px #ff224433; border-top-color: #ff6666; }
  70%  { box-shadow: 0 0 25px  3px #ff224433, inset 0 0  40px #ff224422; border-top-color: #ff4455; }
  100% { box-shadow: inset 0 0 20px #ff224411; border-top-color: #ff2244; }
}

/* Double-burst strobe */
@keyframes strobeFlash {
  0%,100% { opacity: 0; }
  4%       { opacity: 0.18; }
  8%       { opacity: 0; }
  54%      { opacity: 0; }
  57%      { opacity: 0.12; }
  60%      { opacity: 0; }
}

/* Scrolling CRT scanlines */
@keyframes scanlineScroll {
  from { background-position: 0 0; }
  to   { background-position: 0 200px; }
}

/* ── body.glitch-mode: shake + RGB shift ── */
body.glitch-mode {
  animation: screenShake 0.11s steps(1) infinite,
             rgbBodyShift 0.35s infinite;
  overflow-x: hidden;
}

/* Scrolling scanlines layer */
body.glitch-mode::before {
  content: '';
  position: fixed; inset: 0;
  z-index: 9985;
  pointer-events: none;
  background: repeating-linear-gradient(
    0deg,
    transparent       0,
    transparent       3px,
    rgba(0,0,0,0.14)  3px,
    rgba(0,0,0,0.14)  4px
  );
  animation: scanlineScroll 0.5s linear infinite;
}

/* Red strobe layer */
body.glitch-mode::after {
  content: '';
  position: fixed; inset: 0;
  pointer-events: none;
  z-index: 9986;
  background: #ff2244;
  animation: strobeFlash 1.3s infinite;
}

/* ── Danger element states ── */
.index-main.danger   { animation: alarmPulse 0.6s infinite; }
.index-number.danger { animation: glitch 0.16s infinite; }
.index-status.danger { animation: glitch 0.28s infinite; }
.progress-bar.danger {
  animation: blink 0.2s infinite;
  background: linear-gradient(90deg, #ff2244, #ff6600);
}

/* ── Alarm overlay ── */
#alarmOverlay {
  position: fixed; inset: 0;
  pointer-events: none;
  z-index: 9984;
  display: none;
  background: #ff2244;
  animation: strobeFlash 1.3s infinite;
}
#alarmOverlay.active { display: block; }

/* ── JS-injected glitch bars ── */
.glitch-bar {
  position: fixed;
  left: 0; right: 0;
  pointer-events: none;
  z-index: 9988;
  mix-blend-mode: screen;
}

/* PROGRESS BAR */
.progress-wrap {
  margin-top: 32px;
  height: 6px;
  background: #0d1f2d;
  position: relative;
  overflow: hidden;
}

.progress-bar {
  height: 100%;
  background: linear-gradient(90deg, var(--green), #00ddff);
  transition: width 2s cubic-bezier(0.4, 0, 0.2, 1), background 1s;
  box-shadow: 0 0 12px #00ff8888;
}

.progress-bar.warn {
  background: linear-gradient(90deg, var(--yellow), #ff8800);
}


/* STATS GRID */
.stats-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 16px;
  margin-top: 24px;
}

@media(max-width:600px) {
  .stats-grid {
    grid-template-columns: 1fr;
  }
}

.stat-card {
  background: var(--panel);
  border: 1px solid var(--border);
  padding: 24px;
  position: relative;
  overflow: hidden;
}

.stat-card::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 1px;
  background: linear-gradient(90deg, transparent, var(--green), transparent);
  opacity: 0.4;
}

.stat-value {
  font-family: 'Bebas Neue', sans-serif;
  font-size: clamp(32px, 5vw, 48px);
  color: #e0f0f8;
  letter-spacing: 0.05em;
}

.stat-label {
  font-size: 10px;
  letter-spacing: 0.35em;
  color: #2a5060;
  text-transform: uppercase;
  margin-top: 4px;
}

.stat-change {
  font-size: 11px;
  margin-top: 8px;
}

.stat-change.up {
  color: var(--green);
}

.stat-change.down {
  color: var(--red);
}

/* LIVE FEED */
.feed-wrap {
  background: var(--panel);
  border: 1px solid var(--border);
  margin-top: 24px;
}

.feed-header {
  padding: 16px 24px;
  border-bottom: 1px solid var(--border);
  display: flex;
  align-items: center;
  gap: 10px;
  font-size: 11px;
  letter-spacing: 0.3em;
  color: #2a5060;
}

.live-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--green);
  box-shadow: 0 0 8px var(--green);
  animation: live-pulse 1.5s infinite;
}

@keyframes live-pulse {

  0%,
  100% {
    opacity: 1
  }

  50% {
    opacity: 0.3
  }
}

.feed-list {
  max-height: 240px;
  overflow: hidden;
  position: relative;
}

.feed-list::after {
  content: '';
  position: absolute;
  bottom: 0;
  left: 0;
  right: 0;
  height: 60px;
  background: linear-gradient(transparent, var(--panel));
}

.feed-item {
  padding: 12px 24px;
  border-bottom: 1px solid #0a1820;
  display: flex;
  align-items: center;
  gap: 12px;
  font-size: 11px;
  animation: slide-in 0.4s ease;
}

@keyframes slide-in {
  from {
    transform: translateY(-10px);
    opacity: 0
  }
}

.feed-badge {
  padding: 2px 8px;
  font-size: 9px;
  letter-spacing: 0.2em;
}

.feed-badge.human {
  border: 1px solid var(--green);
  color: var(--green);
}

.feed-badge.bot {
  border: 1px solid var(--red);
  color: var(--red);
}

.feed-addr {
  color: #3a6070;
  flex: 1;
}

.feed-amount {
  color: #e0f0f8;
}

.feed-time {
  color: #1a3040;
}

/* ---- ABOUT SECTION ---- */
.about-section {
  position: relative;
  padding: 80px 20px;
  overflow: hidden;
}

.about-bg {
  position: absolute;
  inset: 0;
  background-image: url('data:image/jpeg;base64,');
  background-size: cover;
  background-position: center top;
  filter: brightness(0.12) saturate(0.8);
}

.about-content {
  position: relative;
  z-index: 1;
}

.two-col {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 48px;
  align-items: center;
}

@media(max-width:700px) {
  .two-col {
    grid-template-columns: 1fr;
  }
}

.about-text p {
  font-family: 'Rajdhani', sans-serif;
  font-size: 17px;
  line-height: 1.8;
  color: #5a8090;
  margin-bottom: 20px;
  font-weight: 300;
}

.about-text p strong {
  color: #c0d8e0;
  font-weight: 600;
}

.about-eye {
  width: 100%;
  max-width: 340px;
  border: 1px solid var(--border);
  display: block;
  margin: 0 auto;
  filter: brightness(0.9) saturate(1.1);
  box-shadow: 0 0 60px #00ff8818;
}

/* MECHANICS */
.mechanics-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 20px;
}

@media(max-width:700px) {
  .mechanics-grid {
    grid-template-columns: 1fr;
  }
}

.mechanic-card {
  background: var(--panel);
  border: 1px solid var(--border);
  padding: 28px;
  position: relative;
  overflow: hidden;
}

.mechanic-num {
  font-family: 'Bebas Neue', sans-serif;
  font-size: 48px;
  color: #0d2030;
  position: absolute;
  top: 12px;
  right: 16px;
  line-height: 1;
}

.mechanic-icon {
  font-size: 28px;
  margin-bottom: 16px;
}

.mechanic-title {
  font-family: 'Rajdhani', sans-serif;
  font-size: 16px;
  font-weight: 700;
  color: #c0d8e0;
  letter-spacing: 0.1em;
  margin-bottom: 10px;
  text-transform: uppercase;
}

.mechanic-text {
  font-family: 'Rajdhani', sans-serif;
  font-size: 14px;
  color: #4a7080;
  line-height: 1.7;
  font-weight: 300;
}

/* TOKENOMICS */
.token-table {
  width: 100%;
  border-collapse: collapse;
}

.token-table tr {
  border-bottom: 1px solid var(--border);
}

.token-table tr:first-child {
  border-top: 1px solid var(--border);
}

.token-table td {
  padding: 16px 0;
  font-size: 13px;
}

.token-table td:first-child {
  color: #2a5060;
  letter-spacing: 0.2em;
  text-transform: uppercase;
}

.token-table td:last-child {
  color: #c0d8e0;
  text-align: right;
}

/* FOOTER */
footer {
  position: relative;
  z-index: 1;
  border-top: 1px solid var(--border);
  padding: 40px 20px;
  text-align: center;
}

.footer-ticker {
  font-family: 'Bebas Neue', sans-serif;
  font-size: 48px;
  color: #0d2030;
  letter-spacing: 0.2em;
}

.footer-links {
  margin-top: 20px;
  display: flex;
  gap: 24px;
  justify-content: center;
}

.footer-links a {
  font-size: 11px;
  letter-spacing: 0.3em;
  color: #1a4050;
  text-decoration: none;
  text-transform: uppercase;
  transition: color 0.2s;
}

.footer-links a:hover {
  color: var(--green);
}

.footer-copy {
  margin-top: 32px;
  font-size: 10px;
  color: #0d2030;
}

/* ALERT BANNER */
.alert-bar {
  background: #0a0005;
  border-bottom: 1px solid #2a0015;
  padding: 10px 20px;
  text-align: center;
  font-size: 11px;
  letter-spacing: 0.2em;
  color: #8a0030;
  display: none;
}

.alert-bar.show {
  display: block;
  animation: blink 2s infinite;
}

/* NAV */
nav {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 100;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 20px 40px;
  background: linear-gradient(to bottom, rgba(2, 5, 8, 0.95), transparent);
  backdrop-filter: blur(4px);
}

.nav-logo {
  font-family: 'Bebas Neue', sans-serif;
  font-size: 24px;
  letter-spacing: 0.15em;
  color: var(--green);
  text-shadow: 0 0 20px #00ff8844;
  display: flex;
  align-items: center;
  gap: 10px;
}

.nav-logo img {
  width: 32px;
  height: 32px;
  border-radius: 50%;
  border: 1px solid #00ff8844;
}

.nav-links {
  display: flex;
  gap: 32px;
}

.nav-links a {
  font-size: 11px;
  letter-spacing: 0.3em;
  text-transform: uppercase;
  color: #2a5060;
  text-decoration: none;
  transition: color 0.2s;
}

.nav-links a:hover {
  color: var(--green);
}

.wallet-btn {
  -webkit-appearance: none;
  appearance: none;
  outline: none;
  font-family: 'Share Tech Mono', monospace;
  font-size: 11px;
  letter-spacing: 0.25em;
  padding: 10px 18px;
  background: rgba(0, 255, 136, 0.07);
  border: 1px solid rgba(0, 255, 136, 0.35);
  color: #00ff88;
  cursor: pointer;
  text-transform: uppercase;
  transition: all 0.3s;
  white-space: nowrap;
  align-self: center;
}
.wallet-btn:hover {
  background: rgba(0, 255, 136, 0.15);
  border-color: #00ff88;
  box-shadow: 0 0 14px #00ff8844;
}

/* ── AMBIENT SOUND BUTTON ── */
.ambient-btn {
  font-family: 'Share Tech Mono', monospace;
  font-size: 11px;
  letter-spacing: 0.2em;
  background: transparent;
  border: 1px solid #0d2030;
  color: #1a4050;
  cursor: pointer;
  padding: 6px 12px;
  transition: all 0.3s;
  -webkit-appearance: none;
  appearance: none;
  align-self: center;
}
.ambient-btn:hover { border-color: #00ff8844; color: #00ff8877; }
.ambient-btn.on { border-color: #00ff8833; color: #00ff8866; box-shadow: 0 0 8px #00ff8822; }

@media(max-width:600px) {
  nav {
    padding: 16px 20px;
  }

  .nav-links {
    display: none;
  }
}


.checker-layout {
  display: flex;
  flex-direction: column;
  gap: 20px;
}
@media (min-width: 900px) {
  .checker-layout { flex-direction: row; }
  .checker-layout .checker-wrap { flex: 1; }
}

.checker-wrap {
  background: var(--panel);
  border: 1px solid var(--border);
  border-top: 2px solid #0066aa;
  padding: 32px;
}

.checker-input-row {
  display: flex;
  gap: 12px;
}

@media(max-width:600px) {
  .checker-input-row {
    flex-direction: column;
  }
}

.ca-input {
  flex: 1;
  background: #030810;
  border: 1px solid var(--border);
  border-radius: 0;
  color: var(--green);
  font-family: 'Share Tech Mono', monospace;
  font-size: 13px;
  padding: 14px 18px;
  outline: none;
  letter-spacing: 0.05em;
  transition: border-color 0.2s;
}

.ca-input:focus {
  border-color: #0066aa;
}

.ca-input::placeholder {
  color: #1a3040;
}

.ca-btn {
  background: transparent;
  border: 1px solid #0066aa;
  color: #0099dd;
  font-family: 'Bebas Neue', sans-serif;
  font-size: 18px;
  letter-spacing: 0.2em;
  padding: 14px 32px;
  cursor: pointer;
  transition: all 0.2s;
  white-space: nowrap;
}

.ca-btn:hover {
  background: #0066aa22;
  color: #00ccff;
}

.checker-examples {
  margin-top: 14px;
  display: flex;
  align-items: center;
  gap: 12px;
  flex-wrap: wrap;
}

.example-ca {
  font-size: 10px;
  letter-spacing: 0.25em;
  color: #1a5060;
  border: 1px solid #0d2030;
  padding: 4px 12px;
  cursor: pointer;
  transition: all 0.2s;
  text-transform: uppercase;
}

.example-ca:hover {
  color: var(--green);
  border-color: var(--green);
}

/* RESULT */
.checker-result {
  margin-top: 28px;
  animation: slide-in 0.4s ease;
}

.checker-result-inner {
  border: 1px solid var(--border);
  padding: 28px;
  background: #030810;
}

.cr-header {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  margin-bottom: 20px;
  flex-wrap: wrap;
  gap: 16px;
}

.cr-addr {
  font-size: 11px;
  color: #2a5060;
  word-break: break-all;
  margin-bottom: 4px;
}

.cr-name {
  font-family: 'Bebas Neue', sans-serif;
  font-size: 28px;
  color: #c0d8e0;
  letter-spacing: 0.1em;
}

.cr-score-wrap {
  text-align: right;
}

.cr-score-label {
  font-size: 9px;
  letter-spacing: 0.4em;
  color: #1a4050;
  margin-bottom: 4px;
}

.cr-score {
  font-family: 'Bebas Neue', sans-serif;
  font-size: 64px;
  line-height: 1;
  letter-spacing: -0.02em;
}

.cr-bar-wrap {
  height: 4px;
  background: #0d1f2d;
  margin-bottom: 24px;
}

.cr-bar {
  height: 100%;
  transition: width 1.5s cubic-bezier(0.4, 0, 0.2, 1), background 1s;
}

.cr-stats {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 16px;
}

@media(max-width:600px) {
  .cr-stats {
    grid-template-columns: repeat(2, 1fr);
  }
}

.cr-stat-val {
  font-family: 'Bebas Neue', sans-serif;
  font-size: 28px;
  color: #c0d8e0;
  letter-spacing: 0.05em;
}

.cr-stat-label {
  font-size: 9px;
  letter-spacing: 0.3em;
  color: #1a4050;
  margin-top: 2px;
}

.cr-verdict-bar {
  margin-top: 20px;
  padding: 12px 16px;
  font-size: 11px;
  letter-spacing: 0.25em;
  text-align: center;
}

/* LOADING */
.checker-loading {
  margin-top: 28px;
  text-align: center;
  padding: 40px;
}

.loading-eye {
  font-size: 40px;
  animation: spin-eye 1s linear infinite;
  display: inline-block;
}

@keyframes spin-eye {
  0% {
    transform: scaleX(1)
  }

  50% {
    transform: scaleX(-1)
  }

  100% {
    transform: scaleX(1)
  }
}

.loading-text {
  margin-top: 16px;
  font-size: 11px;
  letter-spacing: 0.4em;
  color: #1a4050;
  animation: loading-dots 1.5s infinite;
}

@keyframes loading-dots {

  0%,
  100% {
    opacity: 0.3
  }

  50% {
    opacity: 1
  }
}

/* ══════════════════════════════════════
   WITNESS WALL
══════════════════════════════════════ */
.witness-wall {
  margin-top: 24px;
  border-top: 1px solid #00ff8822;
  padding-top: 20px;
}
.witness-wall-title {
  font-size: 10px;
  letter-spacing: 0.45em;
  color: #00ff88;
  margin-bottom: 14px;
  text-shadow: 0 0 10px #00ff8844;
}
.witness-wall-form {
  display: flex;
  gap: 8px;
  margin-bottom: 16px;
}
.witness-wall-input {
  flex: 1;
  background: transparent;
  border: 1px solid #00ff8833;
  color: #00ff88;
  font-family: 'Share Tech Mono', monospace;
  font-size: 11px;
  letter-spacing: 0.15em;
  padding: 8px 12px;
  outline: none;
  transition: border-color 0.2s;
}
.witness-wall-input:focus { border-color: #00ff8877; }
.witness-wall-input::placeholder { color: #1a3040; }
.witness-wall-submit {
  -webkit-appearance: none;
  appearance: none;
  background: transparent;
  border: 1px solid #00ff8844;
  color: #00ff88;
  font-family: 'Share Tech Mono', monospace;
  font-size: 10px;
  letter-spacing: 0.3em;
  padding: 8px 14px;
  cursor: pointer;
  transition: all 0.2s;
  white-space: nowrap;
}
.witness-wall-submit:hover {
  background: rgba(0,255,136,0.08);
  border-color: #00ff88;
  box-shadow: 0 0 10px #00ff8833;
}
.witness-wall-entries {
  display: flex;
  flex-direction: column;
  gap: 5px;
  max-height: 150px;
  overflow-y: auto;
}
.witness-entry {
  font-size: 10px;
  letter-spacing: 0.12em;
  display: flex;
  gap: 10px;
  padding: 5px 0;
  border-bottom: 1px solid #0d1f2d;
  align-items: baseline;
}
.witness-entry-addr { color: #1a5040; flex-shrink: 0; font-size: 9px; }
.witness-entry-msg  { color: #00ff8899; flex: 1; }
.witness-entry-time { color: #1a3040; flex-shrink: 0; font-size: 9px; }
.witness-entry-new  { animation: witnessAppear 0.4s ease; }
@keyframes witnessAppear {
  from { opacity: 0; transform: translateX(-8px); }
  to   { opacity: 1; transform: translateX(0); }
}

/* ══════════════════════════════════════
   KONAMI CODE OVERLAY
══════════════════════════════════════ */
#konamiOverlay {
  position: fixed; inset: 0;
  z-index: 10000;
  background: #000;
  display: none;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  cursor: pointer;
}
#konamiOverlay.active { display: flex; animation: konamiFadeIn 0.5s ease; }
@keyframes konamiFadeIn {
  from { opacity: 0; }
  to   { opacity: 1; }
}
.konami-noise {
  position: absolute; inset: 0;
  background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 256 256' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.9' numOctaves='4'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='0.04'/%3E%3C/svg%3E");
  pointer-events: none;
  opacity: 0.5;
  animation: noiseShift 0.08s steps(1) infinite;
}
@keyframes noiseShift {
  0%   { transform: translate(0,0); }
  25%  { transform: translate(-2px,1px); }
  50%  { transform: translate(2px,-1px); }
  75%  { transform: translate(-1px,2px); }
  100% { transform: translate(1px,-2px); }
}
.konami-line {
  font-family: 'Share Tech Mono', monospace;
  font-size: 11px;
  letter-spacing: 0.5em;
  color: #1a5040;
  margin-bottom: 32px;
  opacity: 0;
  animation: konamiReveal 0.5s ease 0.2s forwards;
}
.konami-main {
  font-family: 'Bebas Neue', sans-serif;
  font-size: clamp(36px, 9vw, 90px);
  letter-spacing: 0.08em;
  color: #fff;
  text-shadow: 0 0 60px rgba(255,255,255,0.3);
  text-align: center;
  line-height: 1.1;
  opacity: 0;
  animation: konamiReveal 0.6s ease 0.5s forwards;
}
.konami-sub {
  font-family: 'Bebas Neue', sans-serif;
  font-size: clamp(28px, 7vw, 70px);
  letter-spacing: 0.2em;
  color: #00ff88;
  text-shadow: 0 0 40px #00ff8866;
  margin-top: 8px;
  opacity: 0;
  animation: konamiReveal 0.6s ease 0.9s forwards;
}
.konami-msg {
  font-family: 'Share Tech Mono', monospace;
  font-size: 11px;
  letter-spacing: 0.35em;
  color: #2a5040;
  margin-top: 40px;
  opacity: 0;
  animation: konamiReveal 0.5s ease 1.4s forwards;
}
.konami-hint {
  position: absolute; bottom: 40px;
  font-family: 'Share Tech Mono', monospace;
  font-size: 10px;
  letter-spacing: 0.3em;
  color: #1a2a30;
  opacity: 0;
  animation: konamiReveal 0.5s ease 1.8s forwards;
}
@keyframes konamiReveal {
  from { opacity: 0; transform: translateY(16px); }
  to   { opacity: 1; transform: translateY(0); }
}

/* ── EKG HEARTBEAT ── */
#ekgWrap canvas { background: #030810; border: 1px solid #0d2030; }

/* ── PROOF OF WITNESS CERTIFICATE BUTTON ── */
.witness-cert-btn {
  display: block;
  width: 100%;
  margin-top: 16px;
  background: transparent;
  border: 1px solid #00ff8844;
  color: #00ff88;
  font-family: 'Share Tech Mono', monospace;
  font-size: 11px;
  letter-spacing: 0.3em;
  padding: 12px;
  cursor: pointer;
  transition: all 0.3s;
  -webkit-appearance: none;
  appearance: none;
  text-align: center;
  box-sizing: border-box;
}
.witness-cert-btn:hover {
  background: #00ff8808;
  border-color: #00ff88;
  box-shadow: 0 0 15px #00ff8833;
}
